import { createPublicClient, createWalletClient, http, type Address } from 'viem';
import { privateKeyToAccount } from 'viem/accounts';
import { REGISTRIES, IDENTITY_REGISTRY_ABI } from './constants';
import type { CreateAgentIdentityOptions, AgentIdentity, RegistrationFile, GenerateRegistrationOptions, GenerateAgentCardOptions, AgentCard } from './types';

export async function createAgentIdentity(options: CreateAgentIdentityOptions): Promise<AgentIdentity> {
    const { rpcUrl, privateKey, autoRegister, agentURI } = options;
    let { chainId } = options;

    if (typeof chainId === 'string') {
        // Map string to standard number if provided
        const mappedId = require('./constants').NETWORK_NAMES[chainId.toLowerCase()];
        if (mappedId) {
            chainId = mappedId;
        } else {
            const parsed = parseInt(chainId, 10);
            if (!isNaN(parsed)) {
                chainId = parsed;
            } else {
                throw new Error(`Unknown network name or invalid chainId: ${chainId}`);
            }
        }
    }

    if (!privateKey) {
        throw new Error('A privateKey is currently required for createAgentIdentity');
    }

    const account = privateKeyToAccount(privateKey as `0x${string}`);
    const walletAddress = account.address;

    const publicClient = createPublicClient({
        transport: http(rpcUrl),
    });

    const walletClient = createWalletClient({
        account,
        transport: http(rpcUrl),
    });

    const registries = REGISTRIES[chainId];
    if (!registries || !registries.IdentityRegistry) {
        throw new Error(`IdentityRegistry not found for chain ${chainId}`);
    }

    const identityRegistry = registries.IdentityRegistry as Address;
    const agentRegistryStr = `eip155:${chainId}:${identityRegistry}`;

    let agentId: string | undefined;

    // Let's assume autoRegister logic attempts to mint a new agent for the sake of the example API requested.
    // In a real scenario, you'd check if the address already owns an agent NFT.
    if (autoRegister) {
        try {
            const { request } = await publicClient.simulateContract({
                address: identityRegistry,
                abi: IDENTITY_REGISTRY_ABI,
                functionName: 'register',
                args: agentURI ? [agentURI] : [],
                account
            });
            const hash = await walletClient.writeContract(request);
            const receipt = await publicClient.waitForTransactionReceipt({ hash });

            // Very basic log parsing to grab agentId (transfer event emitted in ERC721)
            // Since viem simulation returns request but doesn't easily expose the return id, we check events
            if (receipt.logs.length > 0) {
                // We assume the first log is the Transfer event
                const transferEvent = receipt.logs[0];
                // Topics[3] usually contains the tokenId in ERC721
                if (transferEvent.topics[3]) {
                    agentId = BigInt(transferEvent.topics[3]).toString();
                }
            }
        } catch (e: any) {
            console.error('Failed to auto-register:', e);
            // Fallback or handle accordingly depending on error
        }
    }

    // If we still don't have an agentId (maybe autoRegister=false or it failed), we default to a placeholder
    // A robust implementation would either require an agentId from the config or search the chain
    if (!agentId) {
        agentId = "0"; // Placeholder or generic default for unregistered instances
        console.warn('No agentId retrieved. Continuing with placeholder agentId="0".');
    }

    return {
        agentId,
        agentRegistry: agentRegistryStr,
        walletAddress,
        chainId: chainId as number,
        privateKey
    };
}

export async function generateAgentRegistration(identity: AgentIdentity, metadata: GenerateRegistrationOptions): Promise<RegistrationFile> {
    const x402Support = metadata.x402Support ?? false;

    // Parse the agentId down to a numeric standard as per ERC-8004 draft specifications
    let agentIdNumeric = 0;
    if (identity.agentId) {
        agentIdNumeric = parseInt(identity.agentId, 10);
        if (isNaN(agentIdNumeric)) agentIdNumeric = 0;
    }

    const registrations = metadata.registrations || [
        {
            agentId: agentIdNumeric,
            agentRegistry: identity.agentRegistry
        }
    ];

    return {
        type: "https://eips.ethereum.org/EIPS/eip-8004#registration-v1",
        name: metadata.name,
        description: metadata.description,
        image: metadata.image,
        services: metadata.services || [],
        registrations,
        x402Support,
        active: metadata.active ?? true,
        supportedTrust: metadata.supportedTrust || ["reputation"]
    };
}

export function generateAgentCard(metadata: GenerateAgentCardOptions): AgentCard {
    return {
        protocolVersion: metadata.protocolVersion || "1.0",
        name: metadata.name,
        description: metadata.description || '',
        url: metadata.url,
        supportedInterfaces: metadata.supportedInterfaces || [],
        version: metadata.version || "0.0.1",
        capabilities: metadata.capabilities || { streaming: false, pushNotifications: false, stateTransitionHistory: true },
        defaultInputModes: metadata.defaultInputModes || ["application/json"],
        defaultOutputModes: metadata.defaultOutputModes || ["application/json", "text/plain"],
        skills: metadata.skills || [],
        supportsAuthenticatedExtendedCard: metadata.supportsAuthenticatedExtendedCard ?? false,
        entrypoints: metadata.entrypoints || {},
        payments: metadata.payments || []
    };
}
