import type { Address } from 'viem';

export type ChainId = number;
export type AgentId = string;
export type URI = string;

export enum EndpointType {
    MCP = 'mcp',
    A2A = 'a2a',
    ENS = 'ens',
    DID = 'did',
    WALLET = 'wallet',
}

export enum TrustModel {
    REPUTATION = 'reputation',
    CRYPTO_ECONOMIC = 'crypto-economic',
    TEE_ATTESTATION = 'tee-attestation',
}

export interface RegistrationService {
    name: string;
    endpoint: string;
    version?: string;
    skills?: string[];
    domains?: string[];
}

export interface RegistrationEntry {
    agentId: number;
    agentRegistry: string;
}

export interface RegistrationFile {
    type: string;
    name: string;
    description: string;
    image?: string;
    services: RegistrationService[];
    registrations: RegistrationEntry[];
    x402Support: boolean;
    active: boolean;
    supportedTrust: string[];
}

export interface AgentCardSkill {
    id: string;
    name: string;
    description: string;
    inputModes: string[];
    outputModes: string[];
    streaming: boolean;
    x_input_schema?: any;
    x_output_schema?: any;
}

export interface AgentCardEntrypoint {
    description: string;
    streaming: boolean;
    input_schema?: any;
    output_schema?: any;
    pricing?: { invoke: string };
}

export interface AgentCardPayment {
    method: string;
    payee: string;
    network: string;
    endpoint: string;
    extensions?: any;
}

export interface AgentCard {
    protocolVersion: string;
    name: string;
    description: string;
    url?: string;
    supportedInterfaces?: { url: string; protocolBinding: string }[];
    version: string;
    capabilities?: { streaming: boolean; pushNotifications: boolean; stateTransitionHistory: boolean;[key: string]: boolean };
    defaultInputModes?: string[];
    defaultOutputModes?: string[];
    skills?: AgentCardSkill[];
    supportsAuthenticatedExtendedCard?: boolean;
    entrypoints?: Record<string, AgentCardEntrypoint>;
    payments?: AgentCardPayment[];
}

export interface AgentIdentity {
    agentId: string;
    agentRegistry: string;
    walletAddress?: Address;
    chainId: number;
    privateKey?: string;
}

export interface CreateAgentIdentityOptions {
    rpcUrl: string;
    chainId: number | string;
    privateKey?: string;
    autoRegister?: boolean;
    agentURI?: string;
}

export type GenerateRegistrationOptions = Partial<Omit<RegistrationFile, 'type'>> & {
    name: string;
    description: string;
};

export type GenerateAgentCardOptions = Partial<AgentCard> & {
    name: string;
};
